.account-hub-step {
  grid-area: body;
  display: grid;
  grid-template-rows: auto 1fr;
  gap: var(--hub-header-body-gap);

  &:is(email-exchange-settings) {
    gap: var(--space-xlarge);
  }
}

.account-hub-form,
.account-hub-success-container,
.account-hub-address-book-form {
  max-block-size: 40vh;
  display: flex;
  flex-direction: column;
  block-size: 100%;
  overflow-y: auto;
  justify-content: space-around;
  padding-block-end: 2px;
}

.account-hub-address-book-form,
.account-hub-exchange-settings-form {
  justify-content: start;
}

.account-hub-view {
  display: grid;
  grid-template: "header" min-content "body" 1fr "footer" min-content;
  text-align: center;
  z-index: 1;
  max-block-size: 90vh;
  padding-inline: 20px;
  padding-block-start: 40px;
  border-radius: inherit;
  border: 1px solid var(--hub-border-color);
  /* Background color to better hide loading of the webp (>=100ms) */
  background-color: var(--color-surface-base);
  background-image: light-dark(url("chrome://messenger/skin/images/accounthub-bg-light.webp"), url("chrome://messenger/skin/images/accounthub-bg-dark.webp"));
  background-position: center center;
  background-repeat: no-repeat;
  background-size: cover;

  &.busy {
    cursor: wait;
  }

  #loadingOverlay {
    display: none;
    opacity: 0;
  }

  &.spinner #loadingOverlay {
    display: grid;
    position: absolute;
    inset: 0;
    place-items: center;
    background-color: var(--hub-loader-background);
    opacity: 0.8;
    z-index: 2;
    border-radius: inherit;

    @media (prefers-reduced-motion: no-preference) {
      animation: 0.5s linear 0s hub-reveal-loader;
    }
  }
}
